let input;
try {
	input = JSON.parse(fs.readFileSync(0, "utf8"));
} catch {
	process.exit(0);
}
try {
	await handleHook(input);
} catch (e) {
	if (e instanceof GitError && /not a git repository/i.test(e.stderr)) process.exit(0);
	process.stderr.write(`stift hook: ${e.message}\n`);
	process.exit(1);
}
process.exit(0);
export {};
